public class Animal
{
    public string Name { get; set; }

    public void Eat() => Console.WriteLine($"{Name} is eating");
    public virtual void Speak() => Console.WriteLine("Some sound");
}

public class Dog : Animal
{
    public void Fetch() => Console.WriteLine($"{Name} is fetching");

    public override void Speak() => Console.WriteLine("Woof!");
}

var dog = new Dog { Name = "Rex" };
dog.Eat();   // Inherited: Rex is eating
dog.Speak(); // Overridden: Woof!
dog.Fetch(); // Dog-specific: Rex is fetching

